INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('2c055004-d5fe-48f5-886a-6e1f3b65c088', 'Common Area Maintenance Charges', '10', '8', 'A).- GASTOS DE ADMINISTRACIÓN Y MANTENIMIENTO', E'- The tenant must pay the landlord an additional 15% of the monthly rent plus VAT for administration and maintenance costs.\n- This payment is based on the current rent amount at the time the payment is due.\n- The tenant cannot demand an account of how these funds are used or influence the management or maintenance of the shopping center.\n- The landlord must use these funds to maintain, repair, and replace parts of the shopping center to keep it in good working condition.\n- In cases of unforeseen events or force majeure, neither party is responsible for damages related to service issues at the shopping center.\n- Such issues do not allow the tenant to terminate the contract, claim construction defects, or withhold or reduce rent.', E'La Arrendataria se obliga a cubrir a la Arrendadora por concepto de gastos de administración y mantenimiento una cantidad equivalente al 15% (quince por ciento) del importe de la renta mensual más el impuesto al valor agregado. Cada pago mensual por este concepto será calculado sobre el importe de la renta vigente a la fecha en que sea exigible dicho pago. La Arrendataria acepta expresamente que no tendrá derecho a exigir rendición de cuentas respecto a las cantidades que pague por dichos conceptos, ni podrá intervenir para determinar el tipo o las características de la administración o mantenimiento del Centro Comercial, sin embargo, el Arrendador tendrá la obligación de usar los fondos para mantener, reparar y reemplazar el Centro Comercial y los elementos del mismo de para mantener en óptimas condiciones de funcionamiento.\n\nEn casos fortuitos y/o fuerza mayor, las partes no serán responsables una con la otra por cualquier daño o perjuicio derivado de la calidad, cantidad, falla, falta de disponibilidad, discontinuidad o interrupción en el suministro de cualquier servicio derivado de la cuota de mantenimiento y/o del Centro Comercial y dichas anomalías no serán: (i) causa de terminación de éste contrato; (ii) consideradas un vicio oculto o defecto de construcción a cargo de la Arrendadora; o (iii). un derecho, motivo o facultad de la Arrendataria para retener o reducir la Renta o incumplir cualquier otra obligación a su cargo derivada de éste Contrato.');
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('2c055004-d5fe-48f5-886a-6e1f3b65c088', 'Costos de Publicidad', '10', '8', 'B).- GASTOS DE PUBLICIDAD ORDINARIOS', E'- The Tenant will pay the Landlord an amount equal to 8% of the monthly rent plus VAT for advertising expenses.\n- The Tenant agrees not to demand an accounting of these payments or influence the type or characteristics of the shopping center''s advertising.\n- The Landlord must use these funds for advertising efforts consistent with a shopping center''s presence in media.', 'La Arrendataria cubrirá a la Arrendadora por gastos de Publicidad una cantidad equivalente al 8% (ocho por ciento) del importe de la renta mensual más el impuesto al valor agregado. La Arrendataria acepta expresamente que no tendrá derecho a exigir rendición de cuentas respecto a las cantidades que pague por dicho concepto, ni podrá intervenir para determinar el tipo o las características de la publicidad institucional del Centro Comercial, sin embargo, el Arrendador tendrá la obligación de usar dichos fondos para realizar esfuerzos publicitarios consistentes con un Centro Comercial presente en medios.');
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('2c055004-d5fe-48f5-886a-6e1f3b65c088', 'Percentage Rent', '4', '1.II', 'RENTA PORCENTUAL', E'- The percentage rent is 9% of the monthly Net Sales made at the premises, plus the applicable Value Added Tax (VAT).\n- The tenant will pay the landlord the greater amount between the Fixed Monthly Rent and the Percentage Rent.\n- Each month, the tenant must calculate the total Net Sales to determine if the Percentage Rent exceeds the Fixed Monthly Rent. If it does, the tenant pays the difference.\n- The Percentage Rent, if applicable, must be paid with the Fixed Monthly Rent for the following month.\n- The tenant must submit a monthly sales report to the landlord within the first 10 days of each month, signed by the tenant''s legal representative or designated person.\n- The tenant must also provide special sales reports within 5 business days upon the landlord''s request.\n- The tenant is required to report Net Sales even after the contract ends to determine the rent for the last month.', E'El importe de la renta porcentual es el 9% (nueve por ciento) sobre las Ventas Netas mensuales realizadas en el Local, más el correspondiente Impuesto al Valor Agregado.\n\nComo renta mensual por el uso y goce del Local, la Arrendataria pagará a la Arrendadora, el equivalente a la cantidad que resulte mayor entre la Renta Mensual Fija y la Renta Porcentual.\n\nLa Arrendataria estará obligada a calcular cada mes y durante toda la vigencia del presente Contrato, el total de las Ventas Netas realizadas en el Local para que, siempre y cuando aplique, esta última pague a la Arrendadora el diferencial que resulte de aplicar el porcentaje señalado en la Renta Porcentual, sobre la totalidad de las Ventas Netas, obtenidas durante cada mes dentro del plazo del presente Contrato de Arrendamiento, derivado de la venta neta de los productos y/o servicios que la Arrendataria comercialice en el Local al público en general, si el porcentaje de la misma multiplicado por las Ventas Netas que se hayan generado durante el mes que corresponda es superior a la Renta Mensual Fija pagada. En el entendido de que los conceptos de la Renta Mensual Fija y la Renta Porcentual se considerará en su conjunto para efectos de este Contrato como la Renta Mensual a pagar por parte de la Arrendataria.\n\nSi la Arrendataria tuviere que pagar Renta Porcentual durante la vigencia del presente Contrato, derivado de las Ventas Netas que hubiere generado, el monto de la Renta Porcentual del mes que corresponda (o de ambos en su caso) deberá ser liquidado a la Arrendadora junto con la Renta Mensual Fija del siguiente mes en la fecha en que el pago de la Renta Mensual Fija sea exigible.\n\nLa Arrendataria deberá presentar a la Arrendadora, dentro de los 10 (diez) primeros días de cada mes, un reporte mensual en papel membretado firmado por el apoderado legal de la Arrendataria o la persona que esta última designe para tales efectos. La Arrendataria deberá a su vez, presentar a la Arrendadora reportes especiales de Ventas Netas del Local en cualquier momento dentro de los 5 (cinco) días hábiles siguientes a ser requerido por la Arrendadora, tales reportes abarcarán el periodo y conceptos solicitados por la Arrendadora. La Arrendataria se obliga a reportar las Ventas Netas a la Arrendadora, aún y cuando el presente contrato haya concluido, a efecto de determinar la renta mensual del último mes de vigencia de este documento.');
