a","map_addr_2":"V-04","map_city_state_zip":"Alameda, Mazatlán, Sinaloa 82123","grid_brand":"Planet Fitness","location_created_at":"2025-09-25 19:29:32","active_lease_count_over_time":50873,"location_count_over_time":57649,"remaining_rent_liability_over_time":50873}'::jsonb);
INSERT INTO leases (id, location_id, tenant_company_id, lease_name, lease_type, is_sub_lease, estatus, acquisition_type, lease_classification, rent_commencement_date, delivery_date, expiration_date, expiration_date_including_options, is_month_to_month, number_of_options, each_option_years, remaining_options, remaining_options_years, renewal_notice_period_start, renewal_notice_deadline, renewal_notice_intention, length_of_lease_months, landlord_nombre, landlord_parent_company, landlord_vendor_id, landlord_address1, landlord_address2, landlord_city, landlord_state, landlord_zip, landlord_country, landlord_poc_nombre, landlord_poc_telefono, landlord_poc_email, grace_period_dias, late_fee_type, late_fee_monto, security_deposit, rental_prepayments, rental_prepayments_detalle, remaining_lease_liability, percent_rent_yn, atributos_extra) VALUES ('bfcd1a5d-eaba-4ec7-abff-424360d55e5a', '374124b4-10fb-4bc9-bb28-b6213e80480d', '83602737-ca9f-417e-b1ac-19d0ad371be6', 'Gran Plaza Mazatlán Lease: Bienes Raíces en Promoción de Mazatlán, S.A. de C.V. (02/10/2025 - 02/09/2035)', NULL, false, 'activo', 'Lease', NULL, '2025-06-13', '2025-02-10', '2035-02-09', '2045-02-09', false, 2, NULL, 2, NULL, NULL, '2034-11-09', 'Send Notice to Renew', 119, 'Bienes Raíces en Promoción de Mazatlán, S.A. de C.V.', NULL, NULL, 'Bosque de Alisos 58', 'Primer Piso', 'Bosques de las Lomas, Cuajimalpa de Morelos', 'Ciudad de México', '05120', 'MX', 'Janneth Fernández', NULL, 'jannethfernandez@inmobic.com', 150, 'percent', NULL, NULL, NULL, NULL, NULL, false, '{"lease_most_recent_note":"No","see_lease_for_details":"No","lease_is_silent":"No","rtr_enabled":1}'::jsonb);
INSERT INTO lease_notes (lease_id, titulo, nota, autor_nombre, fecha_nota) VALUES ('bfcd1a5d-eaba-4ec7-abff-424360d55e5a', 'Vigencia', 'Tiene errores de redacción en la carátula referente al Apartado 17.- Plazo del arrendamiento. Además, el clausulado refiere al Apartado 18.- como fecha de término del arrendamiento, sin embargo, el Apartado 18.- señala la fecha de firma del contrato', 'America Gonzalez', NULL);
INSERT INTO lease_notes (lease_id, titulo, nota, autor_nombre, fecha_nota) VALUES ('bfcd1a5d-eaba-4ec7-abff-424360d55e5a', 'Domicilio del Contrato', E'Av. Reforma y Apolo s/n Zona "E" altos, Colonia Alameda, C.P. 82123, en Mazatlán, Sinaloa\nLocal con nomenclatura V-04', 'America Gonzalez', NULL);
INSERT INTO lease_notes (lease_id, titulo, nota, autor_nombre, fecha_nota) VALUES ('bfcd1a5d-eaba-4ec7-abff-424360d55e5a', 'Fecha de Apertura', '24 de mayo de 2025', 'America Gonzalez', NULL);
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('bfcd1a5d-eaba-4ec7-abff-424360d55e5a', 'Late Fees', '14', '17', 'INTERESES MORATORIOS', E'- La tasa de interés por pagos atrasados es del 2% mensual.\n- Se aplica sobre el total de la deuda no pagada a tiempo.\n- Se cobra si el pago se retrasa más de 45 días.\n- El interés se calcula cada mes o parte de mes mientras dure el retraso.\n- Se aplica desde la fecha en que debió hacerse el pago hasta que se pague.', 'La tasa de intereses moratorios será del 2% (dos por ciento) mensual. Esta tasa se aplicará sobre el importe total del adeudo no cubierto puntualmente. Dicho interés moratorio será exigible cuando la Arrendataria se retrase en un pago por más de 45 (cuarenta y cinco) días de la fecha en que debió hacerlo. Este interés mensual se calculará cada mes o fracción de mes, mientras dure la mora, y por todo el tiempo transcurrido desde la fecha inicial en que debió hacerse el pago y hasta la liquidación del mismo.');
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('bfcd1a5d-eaba-4ec7-abff-424360d55e5a', 'Incremento de Renta', '4', '5', 'AJUSTE DE LA RENTA', E'- The Monthly Rent will increase every 12 months starting from June 2025.\n- The increase is based on the change in the National Consumer Price Index (INPC).\n- The INPC is published monthly by the National Institute of Statistics and Geography (INEGI).\n- The rent adjustment compares the INPC from two months before the lease start or last rent adjustment to the INPC from two months before the new adjustment.\n- If the INPC increase is more than 4%, the rent increase will be capped at 4%.', E'Las Partes convienen que la Renta Mensual será incrementada cada 12 (doce) meses, contado a partir de la apertura del local (junio del 2025), se ajustará el importe de la Renta Mensual, incrementándose de acuerdo con la siguiente mecánica: \n\nSe tomará como base el porcentaje que haya variado el Índice Nacional de Precios al Consumidor (INPC), que publica mensualmente el Instituto Nacional de Estadística y Geografía (INEGI), comparando el correspondiente al de dos meses inmediatos anteriores al mes de inicio del arrendamiento o al del último ajuste de renta y el correspondiente al de dos meses inmediatos anteriores al mes en que deba efectuarse el ajuste, en el entendido que si el porcentaje de incremento es mayor al 4% (cuatro por ciento) éste será el porcentaje máximo de incremento de la Renta Mensual.');
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('bfcd1a5d-eaba-4ec7-abff-424360d55e5a', 'Common Area Maintenance Charges', '8', NULL, NULL, 'No applicable information provided.', 'No aplica');
