INSERT INTO leases (id, location_id, tenant_company_id, lease_name, lease_type, is_sub_lease, estatus, acquisition_type, lease_classification, rent_commencement_date, delivery_date, expiration_date, expiration_date_including_options, is_month_to_month, number_of_options, each_option_years, remaining_options, remaining_options_years, renewal_notice_period_start, renewal_notice_deadline, renewal_notice_intention, length_of_lease_months, landlord_nombre, landlord_parent_company, landlord_vendor_id, landlord_address1, landlord_address2, landlord_city, landlord_state, landlord_zip, landlord_country, landlord_poc_nombre, landlord_poc_telefono, landlord_poc_email, grace_period_dias, late_fee_type, late_fee_monto, security_deposit, rental_prepayments, rental_prepayments_detalle, remaining_lease_liability, percent_rent_yn, atributos_extra) VALUES ('0326b15d-1c4b-468a-a0c8-8bb432637a34', '9f038757-7620-4a39-9523-7fac546ca702', '83602737-ca9f-417e-b1ac-19d0ad371be6', 'Xalapa (Paseo Jardines Xalapa) Lease: Inmuebles Sajsa, S.A. de C.V. (12/15/2023 - 12/14/2033)', NULL, false, 'activo', 'Lease', NULL, '2025-06-01', '2023-12-15', '2033-12-14', '2043-12-14', false, 2, NULL, 2, NULL, NULL, '2033-09-14', 'Send Notice to Renew', 119, 'Inmuebles Sajsa, S.A. de C.V.', NULL, NULL, 'Avenida Lázaro Cárdenas 521', NULL, 'Independencia, Jalapa', 'Veracruz', '91170', 'MX', 'Wendy Contreras Galindo', NULL, 'lpin@foadmi.com', 152, 'percent', NULL, NULL, 508040, 'La Arrendataria pagará el importe de 2 (dos) meses de Renta Mensual, equivalente a $508,040.00 (Quinientos ocho mil cuarenta pesos 00/100 M.N.), más IVA (Impuesto al Valor  Agregado), a la entrega del Local Comercial, los cuales se aplicarán automáticamente, a los primeros dos meses  de renta de operación del Local, atendiendo el periodo de gracia establecido en el presente contrato.', 4439488, false, '{"lease_total_rent_next_month":"277468.0000","total_monthly_rent":"277468.0000","annual_gross_rent":"3329616.0000","daily_gross_rent":"9122.23561644","recurring_rent_annual":"3329616.0000","lease_most_recent_note":"No","see_lease_for_details":"No","lease_is_silent":"No","rtr_enabled":1,"base_rent_current_month":"277468.0000","base_rent_next_month":"277468.0000","base_rent_per_square_meter":"1704.00","base_rent_per_year":"3329616.0000"}'::jsonb);
INSERT INTO lease_notes (lease_id, titulo, nota, autor_nombre, fecha_nota) VALUES ('0326b15d-1c4b-468a-a0c8-8bb432637a34', 'Domicilio del Contrato', E'Avenida Lázaro Cárdenas, número 521, Colonia Independencia, Jalapa, Veracruz\nLocal número AN1-04', 'America Gonzalez', NULL);
INSERT INTO lease_notes (lease_id, titulo, nota, autor_nombre, fecha_nota) VALUES ('0326b15d-1c4b-468a-a0c8-8bb432637a34', 'Fecha de Firma del Contrato', '3 de octubre de 2023', 'America Gonzalez', NULL);
INSERT INTO lease_notes (lease_id, titulo, nota, autor_nombre, fecha_nota) VALUES ('0326b15d-1c4b-468a-a0c8-8bb432637a34', 'Fecha de Apertura', '21 de mayo de 2024', 'America Gonzalez', NULL);
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('0326b15d-1c4b-468a-a0c8-8bb432637a34', 'Late Fees', '15', '16', 'INTERESES MORATORIOS', E'- The late payment interest rate is 2% per month.\n- This rate applies to the total amount of the overdue payment.\n- The late fee is charged if the tenant is more than 45 days late on a payment.', 'La tasa de intereses moratorios será del 2% (dos por ciento) mensual. Esta tasa se aplicará sobre el importe total del adeudo no cubierto puntualmente. Dicho interés moratorio será exigible cuando la Arrendataria se retrase en un pago por más de 45 (cuarenta y cinco) días de la fecha en que debió hacerlo.');
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('0326b15d-1c4b-468a-a0c8-8bb432637a34', 'Incremento de Renta', '5', '5', 'AJUSTE DE LA RENTA', E'- The Monthly Rent will increase starting in the fourth year of operation, every January.\n- The increase is based on the change in the National Consumer Price Index (INPC) published by INEGI.\n- The comparison is made between the INPC two months before the lease start or last rent adjustment and two months before the new adjustment.\n- If the increase percentage is more than 7%, the maximum increase will be capped at 7%.', E'Las Partes convienen que la Renta Mensual será incrementada a partir del cuarto año de operación, durante los meses de enero, incrementándose de acuerdo con la siguiente mecánica: \n\nSe tomará como base el porcentaje que haya variado el Índice Nacional de Precios al Consumidor (INPC), que publica mensualmente el Instituto Nacional de Estadística y Geografia (INEGI), comparando el correspondiente al de dos meses inmediatos anteriores al mes de inicio del arrendamiento o al del último ajuste de renta y el correspondiente al de dos meses inmediatos anteriores al mes en que deba efectuarse el ajuste, en el entendido que si el porcentaje de incremento es mayor al 7% (siete por ciento ) éste será el porcentaje máximo de incremento de la Renta Mensual.');
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('0326b15d-1c4b-468a-a0c8-8bb432637a34', 'Common Area Maintenance Charges', '9', '9', 'A).- GASTOS DE ADMINISTRACIÓN Y MANTENIMIENTO', E'- The rent payment includes maintenance fees.\n- The landlord must use these funds to maintain, repair, and replace parts of the shopping center.\n- The goal is to keep the shopping center in optimal working condition.', 'Las Partes acuerdan que en el monto del pago de la renta, está incluye cualquier concepto por cuota de mantenimiento por lo que la Arrendadora tendra la obligación de usar los fondos para mantener, reparar y reemplazar el Centro Comercial y los elementos del mismo para mantenerlos en óptimas condiciones de funcionamiento.');
